struct YC_BIG {
    bool neg;
    std::string digits;
    YC_BIG(): neg(false), digits("0") {}
    YC_BIG(long long v): neg(false), digits("0") {
        unsigned long long mag = 0;
        if (v < 0) {
            neg = true;
            mag = (unsigned long long)(-(v + 1)) + 1ULL;
        } else {
            mag = (unsigned long long)v;
        }
        digits.clear();
        do {
            digits.push_back((char)('0' + (mag % 10ULL)));
            mag /= 10ULL;
        } while (mag > 0ULL);
        std::reverse(digits.begin(), digits.end());
        if (digits == "0") neg = false;
    }
    YC_BIG(int v): YC_BIG((long long)v) {}
    YC_BIG(short v): YC_BIG((long long)v) {}
    YC_BIG(unsigned char v): YC_BIG((long long)v) {}
    YC_BIG(const wchar_t* s): neg(false), digits("0") {
        if (!s) return;
        while (*s && iswspace(*s)) ++s;
        if (*s == L'-') { neg = true; ++s; }
        else if (*s == L'+') { ++s; }
        std::string out;
        while (*s) {
            if (*s >= L'0' && *s <= L'9') out.push_back((char)(*s));
            else if (!iswspace(*s)) break;
            ++s;
        }
        size_t first = 0;
        while (first + 1 < out.size() && out[first] == '0') ++first;
        if (!out.empty()) out = out.substr(first);
        if (out.empty()) { digits = "0"; neg = false; }
        else { digits = out; if (digits == "0") neg = false; }
    }
    YC_BIG(wchar_t* s): YC_BIG((const wchar_t*)s) {}
};

static std::string yc_big_trim_abs(const std::string& in) {
    if (in.empty()) return "0";
    size_t i = 0;
    while (i + 1 < in.size() && in[i] == '0') ++i;
    return in.substr(i);
}

static int yc_big_cmp_abs(const std::string& a, const std::string& b) {
    std::string aa = yc_big_trim_abs(a);
    std::string bb = yc_big_trim_abs(b);
    if (aa.size() != bb.size()) return aa.size() < bb.size() ? -1 : 1;
    if (aa == bb) return 0;
    return aa < bb ? -1 : 1;
}

static std::string yc_big_add_abs(const std::string& a, const std::string& b) {
    std::string aa = yc_big_trim_abs(a);
    std::string bb = yc_big_trim_abs(b);
    int i = (int)aa.size() - 1;
    int j = (int)bb.size() - 1;
    int carry = 0;
    std::string out;
    while (i >= 0 || j >= 0 || carry) {
        int da = i >= 0 ? (aa[(size_t)i] - '0') : 0;
        int db = j >= 0 ? (bb[(size_t)j] - '0') : 0;
        int sum = da + db + carry;
        out.push_back((char)('0' + (sum % 10)));
        carry = sum / 10;
        --i; --j;
    }
    std::reverse(out.begin(), out.end());
    return yc_big_trim_abs(out);
}

static std::string yc_big_sub_abs(const std::string& a, const std::string& b) {
    // 要求 |a| >= |b|
    std::string aa = yc_big_trim_abs(a);
    std::string bb = yc_big_trim_abs(b);
    int i = (int)aa.size() - 1;
    int j = (int)bb.size() - 1;
    int borrow = 0;
    std::string out;
    while (i >= 0) {
        int da = (aa[(size_t)i] - '0') - borrow;
        int db = j >= 0 ? (bb[(size_t)j] - '0') : 0;
        if (da < db) { da += 10; borrow = 1; } else { borrow = 0; }
        out.push_back((char)('0' + (da - db)));
        --i; --j;
    }
    while (out.size() > 1 && out.back() == '0') out.pop_back();
    std::reverse(out.begin(), out.end());
    return yc_big_trim_abs(out);
}

static std::string yc_big_mul_abs(const std::string& a, const std::string& b) {
    std::string aa = yc_big_trim_abs(a);
    std::string bb = yc_big_trim_abs(b);
    if (aa == "0" || bb == "0") return "0";
    std::vector<int> tmp(aa.size() + bb.size(), 0);
    for (int i = (int)aa.size() - 1; i >= 0; --i) {
        for (int j = (int)bb.size() - 1; j >= 0; --j) {
            int p = (aa[(size_t)i] - '0') * (bb[(size_t)j] - '0');
            int idx = i + j + 1;
            int sum = tmp[(size_t)idx] + p;
            tmp[(size_t)idx] = sum % 10;
            tmp[(size_t)(idx - 1)] += sum / 10;
        }
    }
    std::string out;
    size_t i = 0;
    while (i + 1 < tmp.size() && tmp[i] == 0) ++i;
    for (; i < tmp.size(); ++i) out.push_back((char)('0' + tmp[i]));
    return yc_big_trim_abs(out);
}

static void yc_big_runtime_div_zero(const char* op) {
    fprintf(stderr, "! 大整数型运算错误|除数不能为0|%s\n", op ? op : "/");
    fflush(stderr);
    if (IsDebuggerPresent()) DebugBreak();
}

static std::string yc_big_div_abs(const std::string& a, const std::string& b) {
    std::string aa = yc_big_trim_abs(a);
    std::string bb = yc_big_trim_abs(b);
    if (bb == "0") { yc_big_runtime_div_zero("/"); return "0"; }
    if (yc_big_cmp_abs(aa, bb) < 0) return "0";
    std::string cur = "0";
    std::string quo;
    for (size_t i = 0; i < aa.size(); ++i) {
        if (cur == "0") cur = std::string(1, aa[i]);
        else cur.push_back(aa[i]);
        cur = yc_big_trim_abs(cur);
        int q = 0;
        while (yc_big_cmp_abs(cur, bb) >= 0) {
            cur = yc_big_sub_abs(cur, bb);
            ++q;
        }
        quo.push_back((char)('0' + q));
    }
    return yc_big_trim_abs(quo);
}

static std::string yc_big_mod_abs(const std::string& a, const std::string& b) {
    std::string aa = yc_big_trim_abs(a);
    std::string bb = yc_big_trim_abs(b);
    if (bb == "0") { yc_big_runtime_div_zero("%"); return "0"; }
    if (yc_big_cmp_abs(aa, bb) < 0) return aa;
    std::string cur = "0";
    for (size_t i = 0; i < aa.size(); ++i) {
        if (cur == "0") cur = std::string(1, aa[i]);
        else cur.push_back(aa[i]);
        cur = yc_big_trim_abs(cur);
        while (yc_big_cmp_abs(cur, bb) >= 0) {
            cur = yc_big_sub_abs(cur, bb);
        }
    }
    return yc_big_trim_abs(cur);
}

static YC_BIG yc_big_normalized(bool neg, const std::string& digits) {
    YC_BIG out;
    out.digits = yc_big_trim_abs(digits);
    out.neg = (out.digits != "0") ? neg : false;
    return out;
}

static YC_BIG operator-(const YC_BIG& v) {
    return yc_big_normalized(!v.neg, v.digits);
}

static YC_BIG operator+(const YC_BIG& a, const YC_BIG& b) {
    if (a.neg == b.neg) return yc_big_normalized(a.neg, yc_big_add_abs(a.digits, b.digits));
    int cmp = yc_big_cmp_abs(a.digits, b.digits);
    if (cmp == 0) return YC_BIG();
    if (cmp > 0) return yc_big_normalized(a.neg, yc_big_sub_abs(a.digits, b.digits));
    return yc_big_normalized(b.neg, yc_big_sub_abs(b.digits, a.digits));
}

static YC_BIG operator-(const YC_BIG& a, const YC_BIG& b) {
    return a + (-b);
}

static YC_BIG operator*(const YC_BIG& a, const YC_BIG& b) {
    bool neg = (a.neg != b.neg);
    return yc_big_normalized(neg, yc_big_mul_abs(a.digits, b.digits));
}

static YC_BIG operator/(const YC_BIG& a, const YC_BIG& b) {
    bool neg = (a.neg != b.neg);
    return yc_big_normalized(neg, yc_big_div_abs(a.digits, b.digits));
}

static YC_BIG yc_big_mod(const YC_BIG& a, const YC_BIG& b) {
    bool neg = a.neg;
    return yc_big_normalized(neg, yc_big_mod_abs(a.digits, b.digits));
}

static YC_BIG operator%(const YC_BIG& a, const YC_BIG& b) {
    return yc_big_mod(a, b);
}

static bool operator==(const YC_BIG& a, const YC_BIG& b) {
    return a.neg == b.neg && yc_big_trim_abs(a.digits) == yc_big_trim_abs(b.digits);
}

static bool operator!=(const YC_BIG& a, const YC_BIG& b) { return !(a == b); }

static bool operator<(const YC_BIG& a, const YC_BIG& b) {
    if (a.neg != b.neg) return a.neg;
    int cmp = yc_big_cmp_abs(a.digits, b.digits);
    return a.neg ? (cmp > 0) : (cmp < 0);
}

static bool operator>(const YC_BIG& a, const YC_BIG& b) { return b < a; }

static bool operator<=(const YC_BIG& a, const YC_BIG& b) { return !(b < a); }

static bool operator>=(const YC_BIG& a, const YC_BIG& b) { return !(a < b); }

