static void yc_write_utf8_wide(const wchar_t* s) {
    if (!s) return;
    int n = WideCharToMultiByte(CP_UTF8, 0, s, -1, NULL, 0, NULL, NULL);
    if (n <= 1) return;
    char* out = (char*)malloc((size_t)n);
    if (!out) return;
    if (WideCharToMultiByte(CP_UTF8, 0, s, -1, out, n, NULL, NULL) > 0) {
        fwrite(out, 1, (size_t)(n - 1), stdout);
    }
    free(out);
}
static void yc_write_utf8_wide_single_line(const wchar_t* s) {
    const wchar_t* p = s ? s : L"";
    while (*p) {
        if (*p < 32) {
            fputc(' ', stdout);
        } else {
            wchar_t one[2] = { *p, 0 };
            yc_write_utf8_wide(one);
        }
        ++p;
    }
}
static void yc_write_utf8_single_line(const char* s) {
    const char* p = s ? s : "";
    while (*p) {
        if ((unsigned char)(*p) < 32) fputc(' ', stdout);
        else fputc(*p, stdout);
        ++p;
    }
}
