static YC_TEXT yc_utf8_to_wide(const char* s) {
    if (!s) return YC_TEXT();
    int n = MultiByteToWideChar(CP_UTF8, 0, s, -1, NULL, 0);
    if (n <= 1) return YC_TEXT();
    std::wstring out; out.resize((size_t)n - 1);
    if (MultiByteToWideChar(CP_UTF8, 0, s, -1, &out[0], n) <= 0) return YC_TEXT();
    return YC_TEXT(std::move(out));
}

static std::string& yc_c_str_slot(void) {
    static thread_local std::string slots[8];
    static thread_local unsigned slotIdx = 0;
    return slots[(slotIdx++) & 7u];
}

static const char* yc_wide_to_utf8(const wchar_t* s) {
    std::string& out = yc_c_str_slot();
    out.clear();
    if (!s) return out.c_str();
    int n = WideCharToMultiByte(CP_UTF8, 0, s, -1, NULL, 0, NULL, NULL);
    if (n <= 1) return out.c_str();
    out.resize((size_t)n - 1);
    WideCharToMultiByte(CP_UTF8, 0, s, -1, out.data(), n, NULL, NULL);
    return out.c_str();
}

