    size_t len = wcslen(src);
    wchar_t* out = (wchar_t*)malloc(sizeof(wchar_t) * (len + 1));
    if (!out) return NULL;
    memcpy(out, src, sizeof(wchar_t) * (len + 1));
    return out;
}

