static YC_TEXT yc_format_win32_error(DWORD errorCode) {
    if (errorCode == 0) return YC_TEXT();
    LPWSTR sysMsg = NULL;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
        NULL, errorCode, 0, (LPWSTR)&sysMsg, 0, NULL);
    if (!len || !sysMsg) return YC_TEXT();
    while (len > 0 && (sysMsg[len - 1] == L'\r' || sysMsg[len - 1] == L'\n' || sysMsg[len - 1] == L' ' || sysMsg[len - 1] == L'\t')) {
        sysMsg[--len] = 0;
    }
    YC_TEXT out(sysMsg);
    LocalFree(sysMsg);
    return out;
}

static void yc_runtime_report_dll_error(const wchar_t* stage, const wchar_t* dllName, const char* entryName, DWORD errorCode) {
    YC_TEXT winMsg = yc_format_win32_error(errorCode);
    yc_runtime_note_begin();
    yc_runtime_note_part(L"DLL调用失败");
    if (stage && *stage) { yc_runtime_note_part(L"|"); yc_runtime_note_part(stage); }
    if (dllName && *dllName) { yc_runtime_note_part(L"|"); yc_runtime_note_part(dllName); }
    if (entryName && *entryName) { yc_runtime_note_part(L"|"); yc_runtime_note_part(entryName); }
    if (errorCode != 0) { yc_runtime_note_part(L"|"); yc_runtime_note_part((long long)errorCode); }
    if (!winMsg.empty()) { yc_runtime_note_part(L"|"); yc_runtime_note_part((const wchar_t*)winMsg); }
    yc_runtime_note_end();
}

static void yc_runtime_report_dll_text_result(const wchar_t* dllName, const char* entryName) {
    yc_runtime_note_begin();
    yc_runtime_note_part(L"DLL返回空文本");
    if (dllName && *dllName) { yc_runtime_note_part(L"|"); yc_runtime_note_part(dllName); }
    if (entryName && *entryName) { yc_runtime_note_part(L"|"); yc_runtime_note_part(entryName); }
    yc_runtime_note_end();
}

static YC_BIN yc_load_resource_bin(const wchar_t* resourceName) {
    YC_BIN out;
    if (!resourceName || !resourceName[0]) return out;
    HRSRC hRes = FindResourceW(NULL, resourceName, MAKEINTRESOURCEW(10));
    if (!hRes) {
        size_t nameLen = wcslen(resourceName);
        wchar_t* quotedName = (wchar_t*)malloc(sizeof(wchar_t) * (nameLen + 3));
        if (quotedName) {
            quotedName[0] = L'"';
            memcpy(quotedName + 1, resourceName, sizeof(wchar_t) * nameLen);
            quotedName[nameLen + 1] = L'"';
            quotedName[nameLen + 2] = 0;
            hRes = FindResourceW(NULL, quotedName, MAKEINTRESOURCEW(10));
            free(quotedName);
        }
    }
    if (!hRes) return out;
    DWORD size = SizeofResource(NULL, hRes);
    if (size == 0) return out;
    HGLOBAL hData = LoadResource(NULL, hRes);
    if (!hData) return out;
    const unsigned char* bytes = (const unsigned char*)LockResource(hData);
    if (!bytes) return out;
    out.assign(bytes, bytes + size);
    return out;
}

