static YC_TEXT yc_value_to_text(const YC_DATE& d) {
    long long day = (long long)d.v;
    double frac = d.v - (double)day; if (frac < 0) frac = -frac;
    long long secs = (long long)(frac * 86400.0 + 0.5);
    if (secs >= 86400) { secs = 0; day += 1; }
    long long z = day - 25569 + 719468;
    long long era = (z >= 0 ? z : z - 146096) / 146097;
    unsigned long long doe = (unsigned long long)(z - era * 146097);
    unsigned yoe = (unsigned)((doe - doe/1460 + doe/36524 - doe/146096) / 365);
    long long y = (long long)yoe + era * 400;
    unsigned doy = (unsigned)(doe - (365ULL*yoe + yoe/4 - yoe/100));
    unsigned mp = (5*doy + 2)/153;
    unsigned dd = doy - (153*mp+2)/5 + 1;
    unsigned mm = mp < 10 ? mp+3 : mp-9;
    if (mm <= 2) y++;
    wchar_t buf[96];
    if (secs > 0) swprintf(buf, 96, L"%lld年%u月%u日%d时%d分%d秒", y, mm, dd, (int)(secs/3600), (int)((secs%3600)/60), (int)(secs%60));
    else swprintf(buf, 96, L"%lld年%u月%u日", y, mm, dd);
    return YC_TEXT(buf);
}

