    if (value.size() < pos + sizeof(int)) value.resize(pos + sizeof(int), 0);
    memcpy(value.data() + pos, &out, sizeof(int));
}

static void yc_fs_build_root(const wchar_t* driveText, wchar_t outRoot[4]) {
    wchar_t drive = 0;
    if (driveText && driveText[0]) drive = (wchar_t)towupper(driveText[0]);
    if (!drive) {
        int currentDrive = _getdrive();
        if (currentDrive >= 1 && currentDrive <= 26) drive = (wchar_t)(L'A' + currentDrive - 1);
    }
    if (!drive) drive = L'C';
    outRoot[0] = drive;
    outRoot[1] = L':';
    outRoot[2] = L'\\';
    outRoot[3] = L'\0';
}

