typedef INT_PTR (WINAPI *YC_PFN_NOTIFY_LIB)(INT nMsg, DWORD_PTR dwParam1, DWORD_PTR dwParam2);
#define NL_GET_CMD_FUNC_NAMES 14

static YC_PFN_EXECUTE_CMD yc_resolve_cmd_from_module(HMODULE hMod, const char* notifyExport, int cmdIndex) {
    if (!hMod || !notifyExport || cmdIndex < 0) return NULL;
    FARPROC pNotify = GetProcAddress(hMod, notifyExport);
    if (!pNotify) return NULL;
    YC_PFN_NOTIFY_LIB notifyFn = (YC_PFN_NOTIFY_LIB)pNotify;
    const char** cmdNames = (const char**)notifyFn(NL_GET_CMD_FUNC_NAMES, 0, 0);
    if (!cmdNames) return NULL;
    const char* fnName = cmdNames[cmdIndex];
    if (!fnName || !fnName[0]) return NULL;
    return (YC_PFN_EXECUTE_CMD)GetProcAddress(hMod, fnName);
}

extern "C" void yc_invoke_support_cmd(const char* libName, int cmdIndex, YC_MDATA_INF* pRetData, int argCount, YC_MDATA_INF* pArgs) {
    if (!libName || cmdIndex < 0) return;
    YC_PFN_EXECUTE_CMD fn = NULL;
    if (!fn) return;
    fn(pRetData, argCount, pArgs);
}

int yc_text_compare(const wchar_t* left, const wchar_t* right) {
    const wchar_t* lhs = left ? left : L"";
    const wchar_t* rhs = right ? right : L"";
    return lstrcmpW(lhs, rhs);
}

int yc_text_starts_with(const wchar_t* text, const wchar_t* prefix) {
    const wchar_t* src = text ? text : L"";
    const wchar_t* pre = prefix ? prefix : L"";
    size_t preLen = wcslen(pre);
    return wcsncmp(src, pre, preLen) == 0 ? 1 : 0;
}

