/* 标签底图/渐变背景表（懒解码 GDI+ Image）与子类过程 */
typedef struct { int id; int mode; const unsigned char* data; unsigned int size; Gdiplus::Image* img; int gradMode; COLORREF g1; COLORREF g2; COLORREF g3; } YcLblBgEntry;
static YcLblBgEntry g_ycLblBgs[] = {
    { IDC_标签4, 1, NULL, 0, NULL, 2, (COLORREF)255, (COLORREF)65280, (COLORREF)16711680 },
};
static LRESULT CALLBACK YcLblBgProc(HWND h, UINT m, WPARAM w, LPARAM l, UINT_PTR, DWORD_PTR ref) {
    if (m == WM_ERASEBKGND) {
        YcLblBgEntry* e = (YcLblBgEntry*)ref;
        HDC hdc = (HDC)w; RECT rc; GetClientRect(h, &rc);
        FillRect(hdc, &rc, g_hFormBgBrush ? g_hFormBgBrush : GetSysColorBrush(COLOR_BTNFACE));
        if (!e->img && e->data && e->size > 0) {
            HGLOBAL hm = GlobalAlloc(GMEM_MOVEABLE, e->size);
            if (hm) { void* pm = GlobalLock(hm); if (pm) { memcpy(pm, e->data, e->size); GlobalUnlock(hm); }
                IStream* ps = NULL;
                if (CreateStreamOnHGlobal(hm, TRUE, &ps) == S_OK && ps) { e->img = Gdiplus::Image::FromStream(ps, FALSE); if (e->img && e->img->GetLastStatus() != Gdiplus::Ok) { delete e->img; e->img = NULL; } ps->Release(); }
                else { GlobalFree(hm); }
            }
        }
        if (e->img) {
            Gdiplus::Graphics g(hdc); int cw = rc.right - rc.left, ch = rc.bottom - rc.top;
            int iw = (int)e->img->GetWidth(), ih = (int)e->img->GetHeight();
            if (e->mode == 1) { Gdiplus::TextureBrush tb(e->img); g.FillRectangle(&tb, 0, 0, cw, ch); }
            else if (e->mode == 2) { g.DrawImage(e->img, (cw - iw) / 2, (ch - ih) / 2, iw, ih); }
            else if (e->mode == 3) { g.DrawImage(e->img, 0, 0, cw, ch); }
            else { g.DrawImage(e->img, 0, 0, iw, ih); }
        }
        else if (e->gradMode != 0) {
            int cw = rc.right - rc.left, ch = rc.bottom - rc.top;
            if (cw > 0 && ch > 0) {
                Gdiplus::Graphics g(hdc);
                Gdiplus::PointF p0(0.0f, 0.0f), p1(0.0f, (Gdiplus::REAL)ch);
                switch (e->gradMode) {
                    case 1: p0=Gdiplus::PointF(0,0); p1=Gdiplus::PointF(0,(Gdiplus::REAL)ch); break;
                    case 2: p0=Gdiplus::PointF(0,0); p1=Gdiplus::PointF((Gdiplus::REAL)cw,0); break;
                    case 3: p0=Gdiplus::PointF(0,0); p1=Gdiplus::PointF((Gdiplus::REAL)cw,(Gdiplus::REAL)ch); break;
                    case 4: p0=Gdiplus::PointF((Gdiplus::REAL)cw,0); p1=Gdiplus::PointF(0,(Gdiplus::REAL)ch); break;
                    case 5: p0=Gdiplus::PointF(0,(Gdiplus::REAL)ch); p1=Gdiplus::PointF(0,0); break;
                    case 6: p0=Gdiplus::PointF((Gdiplus::REAL)cw,0); p1=Gdiplus::PointF(0,0); break;
                    case 7: p0=Gdiplus::PointF((Gdiplus::REAL)cw,(Gdiplus::REAL)ch); p1=Gdiplus::PointF(0,0); break;
                    case 8: p0=Gdiplus::PointF(0,(Gdiplus::REAL)ch); p1=Gdiplus::PointF((Gdiplus::REAL)cw,0); break;
                }
                Gdiplus::Color c1(255, GetRValue(e->g1), GetGValue(e->g1), GetBValue(e->g1));
                Gdiplus::Color c2(255, GetRValue(e->g2), GetGValue(e->g2), GetBValue(e->g2));
                Gdiplus::Color c3(255, GetRValue(e->g3), GetGValue(e->g3), GetBValue(e->g3));
                Gdiplus::LinearGradientBrush lgb(p0, p1, c1, c3);
                Gdiplus::Color cols[3] = { c1, c2, c3 };
                Gdiplus::REAL poss[3] = { 0.0f, 0.5f, 1.0f };
                lgb.SetInterpolationColors(cols, poss, 3);
                g.FillRectangle(&lgb, 0, 0, cw, ch);
            }
        }
        return 1;
    }
    if (m == WM_NCDESTROY) RemoveWindowSubclass(h, YcLblBgProc, 1);
    return DefSubclassProc(h, m, w, l);
}

