struct YcPicBtnEntry { int id; int type; int checked; int hover; long long tclr; const unsigned char* img[4]; unsigned int imgSize[4]; Gdiplus::Image* decoded[4]; };
static YcPicBtnEntry g_ycPicBtns[] = {
    { IDC_图形按钮1, 0, 0, 0, -1LL, { NULL, NULL, NULL, NULL }, { 0u, 0u, 0u, 0u }, { NULL, NULL, NULL, NULL } },
    { IDC_图形按钮2, 1, 1, 0, 255LL, { NULL, NULL, NULL, NULL }, { 0u, 0u, 0u, 0u }, { NULL, NULL, NULL, NULL } },
};
static YcPicBtnEntry* yc_picbtn_by_id(int id){ if (id <= 0) return NULL; for (size_t i = 0; i < sizeof(g_ycPicBtns)/sizeof(g_ycPicBtns[0]); i++) { if (g_ycPicBtns[i].id == id) return &g_ycPicBtns[i]; } return NULL; }
static Gdiplus::Image* yc_picbtn_img(YcPicBtnEntry* e, int k){
    if (!e || k < 0 || k > 3 || !e->img[k] || !e->imgSize[k]) return NULL;
    if (!e->decoded[k]) {
        HGLOBAL hm = GlobalAlloc(GMEM_MOVEABLE, e->imgSize[k]);
        if (!hm) return NULL;
        void* pm = GlobalLock(hm); if (pm) { memcpy(pm, e->img[k], e->imgSize[k]); GlobalUnlock(hm); }
        IStream* ps = NULL;
        if (CreateStreamOnHGlobal(hm, TRUE, &ps) == S_OK && ps) { Gdiplus::Image* im = Gdiplus::Image::FromStream(ps, FALSE); if (im && im->GetLastStatus() != Gdiplus::Ok) { delete im; im = NULL; } e->decoded[k] = im; ps->Release(); } else { GlobalFree(hm); }
    }
    return e->decoded[k];
}
int yc_picbtn_get_checked(HWND h){ YcPicBtnEntry* e = yc_picbtn_by_id(GetDlgCtrlID(h)); return (e && e->checked) ? 1 : 0; }
void yc_picbtn_set_checked(HWND h, int v){ YcPicBtnEntry* e = yc_picbtn_by_id(GetDlgCtrlID(h)); if (!e) return; e->checked = v ? 1 : 0; if (h) InvalidateRect(h, NULL, TRUE); }
static void yc_picbtn_toggle(HWND h){ YcPicBtnEntry* e = yc_picbtn_by_id(GetDlgCtrlID(h)); if (!e || e->type != 1) return; e->checked = !e->checked; if (h) InvalidateRect(h, NULL, TRUE); }

