static int yc_pb_fkeys(WPARAM w){ int fk=0; if(w & MK_CONTROL) fk|=1; if(w & MK_SHIFT) fk|=2; if(GetKeyState(VK_MENU)&0x8000) fk|=4; return fk; }
static LRESULT CALLBACK YcPicBoxMouseProc(HWND h, UINT m, WPARAM w, LPARAM l, UINT_PTR, DWORD_PTR ref){
    if (m == WM_MOUSEMOVE) { YcPicBtnEntry* pbe = yc_picbtn_by_id(GetDlgCtrlID(h)); if (pbe && !pbe->hover) { pbe->hover = 1; InvalidateRect(h, NULL, TRUE); TRACKMOUSEEVENT tme; tme.cbSize = sizeof(tme); tme.dwFlags = TME_LEAVE; tme.hwndTrack = h; tme.dwHoverTime = 0; TrackMouseEvent(&tme); } }
    else if (m == WM_MOUSELEAVE) { YcPicBtnEntry* pbe = yc_picbtn_by_id(GetDlgCtrlID(h)); if (pbe && pbe->hover) { pbe->hover = 0; InvalidateRect(h, NULL, TRUE); } }
    YcPicBoxMouseEntry* pb = (YcPicBoxMouseEntry*)ref;
    if (pb) {
        bool (*fn)(int,int,int) = NULL;
        switch (m) { case WM_LBUTTONDOWN: fn=pb->ldown; break; case WM_LBUTTONUP: fn=pb->lup; break; case WM_LBUTTONDBLCLK: fn=pb->dbl; break; case WM_RBUTTONDOWN: fn=pb->rdown; break; case WM_RBUTTONUP: fn=pb->rup; break; case WM_MOUSEMOVE: fn=pb->move; break; }
        if (fn && fn((int)(short)LOWORD(l), (int)(short)HIWORD(l), yc_pb_fkeys(w))) return 0;
    }
    if (m == WM_NCDESTROY) RemoveWindowSubclass(h, YcPicBoxMouseProc, 1);
    return DefSubclassProc(h, m, w, l);
}

