        HWND hScroll = (HWND)lParam;
        if (!hScroll) break;
        int sid = GetDlgCtrlID(hScroll);
        { int sc = LOWORD(wParam);
          for (size_t si = 0; si < sizeof(g_ycScrollBars)/sizeof(g_ycScrollBars[0]); si++) {
            if (g_ycScrollBars[si].id != sid) continue;
            SCROLLINFO sinf; ZeroMemory(&sinf, sizeof(sinf)); sinf.cbSize = sizeof(sinf); sinf.fMask = SIF_ALL; GetScrollInfo(hScroll, SB_CTL, &sinf);
            int p = sinf.nPos;
            if (sc==SB_LINELEFT) p-=g_ycScrollBars[si].lineChange; else if (sc==SB_LINERIGHT) p+=g_ycScrollBars[si].lineChange;
            else if (sc==SB_PAGELEFT) p-=g_ycScrollBars[si].pageChange; else if (sc==SB_PAGERIGHT) p+=g_ycScrollBars[si].pageChange;
            else if (sc==SB_THUMBTRACK || sc==SB_THUMBPOSITION) p=sinf.nTrackPos; else if (sc==SB_TOP) p=sinf.nMin; else if (sc==SB_BOTTOM) p=sinf.nMax;
            if (p<sinf.nMin) p=sinf.nMin; if (p>sinf.nMax) p=sinf.nMax;
            SCROLLINFO sset; ZeroMemory(&sset, sizeof(sset)); sset.cbSize = sizeof(sset); sset.fMask = SIF_POS; sset.nPos = p; SetScrollInfo(hScroll, SB_CTL, &sset, TRUE);
