                break;
            }
        }
        return DefWindowProcW(hWnd, message, wParam, lParam);
    }
    case WM_SIZE:
        __启动窗口_窗口尺寸被改变((int)LOWORD(lParam), (int)HIWORD(lParam));
        break;
    case WM_MOVE:
        __启动窗口_被移动((int)(short)LOWORD(lParam), (int)(short)HIWORD(lParam));
        break;
    case WM_ACTIVATE:
        __启动窗口_被激活((int)LOWORD(wParam));
        break;
    case WM_SETFOCUS:
        __启动窗口_得到焦点();
        break;
    case WM_KILLFOCUS:
        __启动窗口_失去焦点();
        break;
    case WM_CLOSE:
        __启动窗口_即将被销毁();
        DestroyWindow(hWnd);
        break;
    case WM_DESTROY:
        __启动窗口_被销毁();
