typedef std::vector<unsigned char> YC_BIN;
static inline YC_BIN operator+(const YC_BIN& a, const YC_BIN& b) { YC_BIN r; r.reserve(a.size() + b.size()); r.insert(r.end(), a.begin(), a.end()); r.insert(r.end(), b.begin(), b.end()); return r; }
struct YC_TEXT {
    std::wstring s;
    YC_TEXT() {}
    YC_TEXT(const wchar_t* p) : s(p ? p : L"") {}
    YC_TEXT(const std::wstring& w) : s(w) {}
    YC_TEXT(std::wstring&& w) : s(std::move(w)) {}
    operator const wchar_t*() const { return s.c_str(); }
    const wchar_t* c_str() const { return s.c_str(); }
    bool empty() const { return s.empty(); }
};

struct YC_DATE {
    double v;
    YC_DATE() : v(0.0) {}
    YC_DATE(double d) : v(d) {}
    operator double() const { return v; }
};

