static YC_BIN* yc_bin_dup(const YC_BIN& b) { return new YC_BIN(b); }
static YC_BIN yc_bin_lit(std::initializer_list<long long> v) { YC_BIN r; r.reserve(v.size()); for (long long b : v) r.push_back((unsigned char)(b & 0xFF)); return r; }
static YC_BIN yc_bin_concat(const YC_BIN& a, const YC_BIN& b) { YC_BIN r(a); r.insert(r.end(), b.begin(), b.end()); return r; }
