static std::vector<long long> yc_ary_lit_bin(std::initializer_list<YC_BIN> v) { std::vector<long long> r; r.reserve(v.size()); for (const YC_BIN& b : v) r.push_back((long long)(intptr_t)yc_bin_dup(b)); return r; }

static std::vector<long long> yc_ary_take(void* p) {
    std::vector<long long>* v = reinterpret_cast<std::vector<long long>*>(p);
    if (!v) return std::vector<long long>();
    std::vector<long long> r = std::move(*v);
    delete v;
    return r;
}
static std::vector<long long> yc_ary_tmp_slots[8];
static int yc_ary_tmp_pos = 0;
static std::vector<long long>& yc_ary_tmp(std::vector<long long> v) {
    std::vector<long long>& s = yc_ary_tmp_slots[yc_ary_tmp_pos];
    yc_ary_tmp_pos = (yc_ary_tmp_pos + 1) % 8;
    s = std::move(v);
    return s;
}
static YC_BIN yc_bin_tmp_slots[8];
