static long long yc_dbg_read_cmd_token(void) {
    FILE* fp = _wfopen(L".ycdbg_cmd", L"rb");
    if (!fp) return g_yc_dbg_resume_token;
    char buf[64] = { 0 };
    size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
    fclose(fp);
    buf[n] = 0;
    return _strtoi64(buf, NULL, 10);
}

static void yc_dbg_wait_for_resume(void) {
    yc_dbg_break_end();
    for (;;) {
        long long token = yc_dbg_read_cmd_token();
        if (token > g_yc_dbg_resume_token) {
            g_yc_dbg_resume_token = token;
            break;
        }
        MSG msg;
        while (PeekMessageW(&msg, NULL, 0, 0, PM_REMOVE)) {
            if (msg.message == WM_QUIT) {
                PostQuitMessage((int)msg.wParam);
                return;
            }
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }
        Sleep(20);
    }
}

