    if (start >= value.size() || n == 0) return YC_BIN();
    if (start + n > value.size()) n = value.size() - start;
    return YC_BIN(value.begin() + start, value.begin() + start + n);
}

static int yc_bin_find(const YC_BIN& haystack, const YC_BIN& needle, int startPos) {
    size_t start = yc_bin_pos_to_index(startPos <= 0 ? 1 : startPos, haystack.size());
    if (needle.empty()) return start < haystack.size() ? (int)start + 1 : 1;
    if (start >= haystack.size() || needle.size() > haystack.size()) return -1;
    auto it = std::search(haystack.begin() + start, haystack.end(), needle.begin(), needle.end());
    return it == haystack.end() ? -1 : (int)(it - haystack.begin()) + 1;
}

static int yc_bin_rfind(const YC_BIN& haystack, const YC_BIN& needle, int startPos) {
    if (needle.empty()) return haystack.empty() ? 1 : (startPos > 0 ? startPos : (int)haystack.size());
    if (needle.size() > haystack.size()) return -1;
    size_t limit = haystack.size() - needle.size();
    if (startPos > 0) {
      size_t requested = yc_bin_pos_to_index(startPos, haystack.size());
      if (requested < limit) limit = requested;
    }
    for (size_t i = limit + 1; i-- > 0;) {
      if (memcmp(haystack.data() + i, needle.data(), needle.size()) == 0) return (int)i + 1;
      if (i == 0) break;
    }
    return -1;
}

static YC_BIN yc_bin_replace(const YC_BIN& value, int startPos, int replaceLen, const YC_BIN& repl) {
    YC_BIN out = value;
    size_t start = yc_bin_pos_to_index(startPos, out.size());
    size_t len = yc_bin_clamp_count(replaceLen);
    if (start > out.size()) start = out.size();
    if (start + len > out.size()) len = out.size() - start;
    out.erase(out.begin() + start, out.begin() + start + len);
    out.insert(out.begin() + start, repl.begin(), repl.end());
    return out;
}

static YC_BIN yc_bin_replace_sub(const YC_BIN& value, const YC_BIN& from, const YC_BIN& to, int startPos, int replaceCount) {
    YC_BIN out = value;
    if (from.empty()) return out;
    size_t pos = yc_bin_pos_to_index(startPos <= 0 ? 1 : startPos, out.size());
    int done = 0;
    while (pos <= out.size()) {
      auto it = std::search(out.begin() + pos, out.end(), from.begin(), from.end());
      if (it == out.end()) break;
      size_t idx = (size_t)(it - out.begin());
      out.erase(out.begin() + idx, out.begin() + idx + from.size());
      out.insert(out.begin() + idx, to.begin(), to.end());
      pos = idx + to.size();
      done++;
      if (replaceCount > 0 && done >= replaceCount) break;
    }
    return out;
}

static YC_BIN yc_bin_space(int count) {
    return YC_BIN(yc_bin_clamp_count(count), 0);
}

static YC_BIN yc_bin_repeat(int count, const YC_BIN& value) {
    YC_BIN out;
    int times = count < 0 ? 0 : count;
    if (times == 0 || value.empty()) return out;
    out.reserve((size_t)times * value.size());
    for (int i = 0; i < times; i++) out.insert(out.end(), value.begin(), value.end());
    return out;
}

static YC_BIN yc_bin_from_address(long long ptrValue, int len) {
    size_t n = yc_bin_clamp_count(len);
