static int yc_byteswap_i32(int value) {
    unsigned int v = (unsigned int)value;
    v = ((v & 0x000000FFu) << 24) | ((v & 0x0000FF00u) << 8) | ((v & 0x00FF0000u) >> 8) | ((v & 0xFF000000u) >> 24);
    return (int)v;
}

static int yc_bin_get_int(const YC_BIN& value, int offset, int reverseBytes) {
    size_t pos = offset < 0 ? 0u : (size_t)offset;
    int out = 0;
    if (pos + sizeof(int) > value.size()) return 0;
    memcpy(&out, value.data() + pos, sizeof(int));
    return reverseBytes ? yc_byteswap_i32(out) : out;
}

static void yc_bin_set_int(YC_BIN& value, int offset, int data, int reverseBytes) {
    size_t pos = offset < 0 ? 0u : (size_t)offset;
    int out = reverseBytes ? yc_byteswap_i32(data) : data;
    if (value.size() < pos + sizeof(int)) value.resize(pos + sizeof(int), 0);
    memcpy(value.data() + pos, &out, sizeof(int));
}

static void yc_fs_build_root(const wchar_t* driveText, wchar_t outRoot[4]) {
    wchar_t drive = 0;
    if (driveText && driveText[0]) drive = (wchar_t)towupper(driveText[0]);
    if (!drive) {
        int currentDrive = _getdrive();
        if (currentDrive >= 1 && currentDrive <= 26) drive = (wchar_t)(L'A' + currentDrive - 1);
    }
    if (!drive) drive = L'C';
    outRoot[0] = drive;
    outRoot[1] = L':';
    outRoot[2] = L'\\';
    outRoot[3] = L'\0';
}

static int yc_fs_clamp_kb(unsigned long long value) {
    return value > 2147483647ULL ? 2147483647 : (int)value;
}

static int yc_fs_disk_total_kb(const wchar_t* driveText) {
    wchar_t root[4];
    ULARGE_INTEGER freeBytesAvailable, totalBytes, totalFreeBytes;
    yc_fs_build_root(driveText, root);
    if (!GetDiskFreeSpaceExW(root, &freeBytesAvailable, &totalBytes, &totalFreeBytes)) return -1;
    return yc_fs_clamp_kb(totalBytes.QuadPart / 1024ULL);
}

static int yc_fs_disk_free_kb(const wchar_t* driveText) {
    wchar_t root[4];
    ULARGE_INTEGER freeBytesAvailable, totalBytes, totalFreeBytes;
    yc_fs_build_root(driveText, root);
    if (!GetDiskFreeSpaceExW(root, &freeBytesAvailable, &totalBytes, &totalFreeBytes)) return -1;
    return yc_fs_clamp_kb(totalFreeBytes.QuadPart / 1024ULL);
}

static wchar_t* yc_fs_get_disk_label(const wchar_t* driveText) {
    wchar_t root[4];
    wchar_t volumeName[MAX_PATH];
    DWORD serialNumber = 0, maxComponentLen = 0, fileSystemFlags = 0;
    wchar_t fileSystemName[MAX_PATH];
    yc_fs_build_root(driveText, root);
    if (!GetVolumeInformationW(root, volumeName, MAX_PATH, &serialNumber, &maxComponentLen, &fileSystemFlags, fileSystemName, MAX_PATH)) {
        return yc_wcsdup_text(L"");
    }
    return yc_wcsdup_text(volumeName);
}

static int yc_fs_set_disk_label(const wchar_t* driveText, const wchar_t* label) {
    wchar_t root[4];
    yc_fs_build_root(driveText, root);
    return SetVolumeLabelW(root, label ? label : L"") ? 1 : 0;
}

static int yc_fs_change_drive(const wchar_t* driveText) {
    wchar_t root[4];
    if (!driveText || !driveText[0]) return 1;
    yc_fs_build_root(driveText, root);
    return SetCurrentDirectoryW(root) ? 1 : 0;
}

