static int yc_fs_file_exists(const wchar_t* path) {
    DWORD attr;
    if (!path || !path[0]) return 0;
    attr = GetFileAttributesW(path);
    return attr != INVALID_FILE_ATTRIBUTES && !(attr & FILE_ATTRIBUTE_DIRECTORY) ? 1 : 0;
}

static int yc_fs_file_len(const wchar_t* path) {
    WIN32_FILE_ATTRIBUTE_DATA data;
    ULARGE_INTEGER size;
    if (!path || !path[0]) return -1;
    if (!GetFileAttributesExW(path, GetFileExInfoStandard, &data)) return -1;
    if (data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) return -1;
    size.LowPart = data.nFileSizeLow;
    size.HighPart = data.nFileSizeHigh;
    return size.QuadPart > 2147483647ULL ? 2147483647 : (int)size.QuadPart;
}

static int yc_fs_get_attr(const wchar_t* path) {
