    return SetFileAttributesW(path, (DWORD)attr) ? 1 : 0;
}

static wchar_t* yc_fs_get_temp_file_name(const wchar_t* dir) {
    wchar_t tempPath[MAX_PATH];
    wchar_t tempFile[MAX_PATH];
    DWORD pathLen = 0;
    if (dir && dir[0]) {
        wcsncpy(tempPath, dir, MAX_PATH - 1);
        tempPath[MAX_PATH - 1] = L'\0';
    } else {
        pathLen = GetTempPathW(MAX_PATH, tempPath);
        if (pathLen == 0 || pathLen >= MAX_PATH) return yc_wcsdup_text(L"");
    }
    if (!GetTempFileNameW(tempPath, L"YCD", 0, tempFile)) return yc_wcsdup_text(L"");
    DeleteFileW(tempFile);
    return yc_wcsdup_text(tempFile);
}

static YC_BIN yc_fs_read_file_bin(const wchar_t* path) {
    YC_BIN out;
    if (!path || !path[0]) return out;
    std::ifstream in(ycfs::path(path), std::ios::binary);
    if (!in) return out;
    in.seekg(0, std::ios::end);
    std::streamoff size = in.tellg();
    if (size < 0) return out;
    in.seekg(0, std::ios::beg);
    out.resize((size_t)size);
    if (size > 0) in.read((char*)out.data(), size);
    if (!in && size > 0) out.clear();
    return out;
}

static int yc_fs_write_file_bins(const wchar_t* path, const std::vector<YC_BIN>& parts) {
    if (!path || !path[0]) return 0;
    std::ofstream out(ycfs::path(path), std::ios::binary | std::ios::trunc);
    if (!out) return 0;
    for (const YC_BIN& part : parts) {
        if (!part.empty()) out.write((const char*)part.data(), (std::streamsize)part.size());
        if (!out) return 0;
    }
    return 1;
}

static HANDLE g_yc_find_handle = INVALID_HANDLE_VALUE;
static WIN32_FIND_DATAW g_yc_find_data;
static int g_yc_find_attr = 0;
static int yc_fs_find_match(const WIN32_FIND_DATAW* data, int attr) {
    int isDir;
    int required = attr & ~FILE_ATTRIBUTE_DIRECTORY;
    if (!data) return 0;
    if (wcscmp(data->cFileName, L".") == 0 || wcscmp(data->cFileName, L"..") == 0) return 0;
    isDir = (data->dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) ? 1 : 0;
    if (attr == 0) return isDir ? 0 : 1;
    if (isDir && !(attr & FILE_ATTRIBUTE_DIRECTORY)) return 0;
    if (!isDir && (attr & FILE_ATTRIBUTE_DIRECTORY) && required == 0) return 0;
    return ((int)data->dwFileAttributes & required) == required ? 1 : 0;
}

static wchar_t* yc_fs_dir(const wchar_t* pattern, int attr) {
    int firstCall = pattern && pattern[0];
    if (firstCall) {
        if (g_yc_find_handle != INVALID_HANDLE_VALUE) { FindClose(g_yc_find_handle); g_yc_find_handle = INVALID_HANDLE_VALUE; }
        g_yc_find_attr = attr;
        g_yc_find_handle = FindFirstFileW(pattern, &g_yc_find_data);
        if (g_yc_find_handle == INVALID_HANDLE_VALUE) return yc_wcsdup_text(L"");
        do {
            if (yc_fs_find_match(&g_yc_find_data, g_yc_find_attr)) return yc_wcsdup_text(g_yc_find_data.cFileName);
        } while (FindNextFileW(g_yc_find_handle, &g_yc_find_data));
        FindClose(g_yc_find_handle);
        g_yc_find_handle = INVALID_HANDLE_VALUE;
        return yc_wcsdup_text(L"");
    }
    if (g_yc_find_handle == INVALID_HANDLE_VALUE) return yc_wcsdup_text(L"");
    while (FindNextFileW(g_yc_find_handle, &g_yc_find_data)) {
        if (yc_fs_find_match(&g_yc_find_data, g_yc_find_attr)) return yc_wcsdup_text(g_yc_find_data.cFileName);
    }
    FindClose(g_yc_find_handle);
    g_yc_find_handle = INVALID_HANDLE_VALUE;
    return yc_wcsdup_text(L"");
}

