extern "C" void krnln_ll_clear(HWND h);
extern "C" int krnln_ll_add_item(HWND h, const wchar_t* t, int data);
std::vector<unsigned char> yc_ll_get_items(HWND h){ std::vector<unsigned char> b; int n=krnln_ll_count(h); if(n<0) n=0; auto pu=[&](unsigned v){ b.push_back((unsigned char)(v&0xff)); b.push_back((unsigned char)((v>>8)&0xff)); b.push_back((unsigned char)((v>>16)&0xff)); b.push_back((unsigned char)((v>>24)&0xff)); }; pu((unsigned)n); for(int i=0;i<n;i++){ YC_TEXT t=yc_ll_get_text(h,i); const wchar_t* p=(const wchar_t*)t; unsigned wlen=(unsigned)(p?wcslen(p):0); pu(wlen); const unsigned char* raw=(const unsigned char*)(p?p:L""); b.insert(b.end(), raw, raw+(size_t)wlen*sizeof(wchar_t)); } return b; }
void yc_ll_set_items(HWND h, const std::vector<unsigned char>& items){ krnln_ll_clear(h); const unsigned char* d=items.data(); size_t sz=items.size(), off=0; auto gu=[&](unsigned& v)->bool{ if(off+4>sz) return false; v=(unsigned)d[off]|((unsigned)d[off+1]<<8)|((unsigned)d[off+2]<<16)|((unsigned)d[off+3]<<24); off+=4; return true; }; unsigned count; if(!gu(count)) return; for(unsigned i=0;i<count;i++){ unsigned wlen; if(!gu(wlen)) break; size_t bytes=(size_t)wlen*sizeof(wchar_t); if(off+bytes>sz) break; std::wstring s((const wchar_t*)(d+off), wlen); off+=bytes; krnln_ll_add_item(h, s.c_str(), 0); } }

/* 编辑框输入方式字符过滤 */
static LRESULT CALLBACK YcEditInputFilterProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam, UINT_PTR uIdSubclass, DWORD_PTR dwRefData) {
    if (message == WM_CHAR) {
        wchar_t ch = (wchar_t)wParam;
        if (ch >= 0x20) {
            int mode = (int)dwRefData;
            int ok = (ch >= L'0' && ch <= L'9');
            if (!ok && ch == L'-' && mode != 5) ok = 1;
            if (!ok && ch == L'.' && (mode == 4 || mode == 9 || mode == 10 || mode == 11)) ok = 1;
            if (!ok && mode == 11 && (ch == L'/' || ch == L':' || ch == L' ')) ok = 1;
            if (!ok) { MessageBeep(MB_OK); return 0; }
        }
    }
    return DefSubclassProc(hWnd, message, wParam, lParam);
}

