HWND yc_get_control_handle_by_name(const wchar_t* ctrlName) {
    if (!ctrlName) return NULL;
    if (lstrcmpW(ctrlName, L"_启动窗口") == 0) return g_hMainWnd;
    for (int pass = 0; pass < 2; pass++) {
        for (size_t i = 0; i < sizeof(g_ycCtrlNames)/sizeof(g_ycCtrlNames[0]); i++) {
            if (!g_ycCtrlNames[i].name) continue;
            if ((pass == 0) != (g_ycCtrlNames[i].win == g_ycCurEventWin)) continue;
            if (lstrcmpW(ctrlName, g_ycCtrlNames[i].name) != 0) continue;
            HWND w = yc_win_handle_by_index(g_ycCtrlNames[i].win);
            if (!w) continue;
            return GetDlgItem(w, g_ycCtrlNames[i].id);
        }
    }
    return NULL;
}

