std::vector<long long> yc_lb_get_sel_items(HWND h){ std::vector<long long> r; if(!h) return r; int cnt=(int)SendMessageW(h, LB_GETSELCOUNT, 0, 0); if(cnt<=0) return r; std::vector<int> ix(cnt); if(SendMessageW(h, LB_GETSELITEMS, (WPARAM)cnt, (LPARAM)ix.data())!=LB_ERR){ for(int i=0;i<cnt;i++) r.push_back((long long)ix[i]); } return r; }

