            if (message == WM_HSCROLL) { _滑块条3_值被改变(); }
            break;
        case IDC_横向滚动条1:
            if (message == WM_HSCROLL) { _横向滚动条1_滚动(); }
            break;
        case IDC_横向滚动条2:
            if (message == WM_HSCROLL) { _横向滚动条2_滚动(); }
            break;
        case IDC_横向滚动条3:
            if (message == WM_HSCROLL) { _横向滚动条3_滚动(); }
            break;
        case IDC_纵向滚动条1:
            if (message == WM_VSCROLL) { _纵向滚动条1_滚动(); }
            break;
        case IDC_纵向滚动条2:
            if (message == WM_VSCROLL) { _纵向滚动条2_滚动(); }
            break;
        case IDC_纵向滚动条3:
            if (message == WM_VSCROLL) { _纵向滚动条3_滚动(); }
            break;
        default:
            break;
        }
        break;
    }
    case WM_CTLCOLOREDIT:
    case WM_CTLCOLORLISTBOX:
    case WM_CTLCOLORSTATIC: {
        int colorCtrlId = GetDlgCtrlID((HWND)lParam);
        HWND hColorParent = GetParent((HWND)lParam);
        int colorParentId = hColorParent ? GetDlgCtrlID(hColorParent) : 0;
        std::map<HWND,COLORREF>::iterator _ovIt = g_ycTextColorOverride.find((HWND)lParam);
        bool _hasOv = (_ovIt != g_ycTextColorOverride.end());
        for (size_t ci = 0; ci < sizeof(g_ycEditColors) / sizeof(g_ycEditColors[0]); ci++) {
            if (g_ycEditColors[ci].id <= 0) continue;
            if (g_ycEditColors[ci].id != colorCtrlId && g_ycEditColors[ci].id != colorParentId) continue;
            SetTextColor((HDC)wParam, _hasOv ? _ovIt->second : g_ycEditColors[ci].textColor);
            if (g_ycEditColors[ci].transparent) { SetBkMode((HDC)wParam, TRANSPARENT); return (LRESULT)GetStockObject(NULL_BRUSH); }
            SetBkColor((HDC)wParam, g_ycEditColors[ci].backColor);
            if (!g_ycEditColors[ci].brush) g_ycEditColors[ci].brush = CreateSolidBrush(g_ycEditColors[ci].backColor);
            return (LRESULT)g_ycEditColors[ci].brush;
        }
        if (_hasOv) {
            SetTextColor((HDC)wParam, _ovIt->second);
            wchar_t ovCls[16] = L""; GetClassNameW((HWND)lParam, ovCls, 16);
            if (message == WM_CTLCOLORSTATIC && _wcsicmp(ovCls, L"EDIT") != 0) {
                SetBkColor((HDC)wParam, (COLORREF)16711680);
                return (LRESULT)(g_hFormBgBrush ? g_hFormBgBrush : GetSysColorBrush(COLOR_BTNFACE));
            }
            SetBkColor((HDC)wParam, GetSysColor(COLOR_WINDOW));
            return (LRESULT)GetSysColorBrush(COLOR_WINDOW);
        }
        if (message == WM_CTLCOLORSTATIC) {
            wchar_t ccCls[16] = L""; GetClassNameW((HWND)lParam, ccCls, 16);
            if (_wcsicmp(ccCls, L"EDIT") != 0) {
            SetBkColor((HDC)wParam, (COLORREF)16711680);
                return (LRESULT)(g_hFormBgBrush ? g_hFormBgBrush : GetSysColorBrush(COLOR_BTNFACE));
            }
        }
        return DefWindowProcW(hWnd, message, wParam, lParam);
    }
    case WM_DRAWITEM: {
        LPDRAWITEMSTRUCT dis = (LPDRAWITEMSTRUCT)lParam;
        if (dis && dis->CtlType == ODT_BUTTON) {
            YcPicBtnEntry* pe = yc_picbtn_by_id((int)dis->CtlID);
            if (pe) {
                RECT rc = dis->rcItem;
                BOOL pbPressed = ((dis->itemState & ODS_SELECTED) != 0) || (pe->type == 1 && pe->checked);
                BOOL pbDisabled = (dis->itemState & ODS_DISABLED) != 0;
                int k = (pbDisabled && pe->img[3]) ? 3 : (pbPressed && pe->img[2]) ? 2 : (pe->hover && pe->type == 0 && pe->img[1]) ? 1 : 0;
                Gdiplus::Image* im = yc_picbtn_img(pe, k);
                if (!im) im = yc_picbtn_img(pe, 0);
                FillRect(dis->hDC, &rc, GetSysColorBrush(COLOR_BTNFACE));
                if (im) {
                    Gdiplus::Graphics g(dis->hDC);
                    g.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic);
                    Gdiplus::Rect dst(rc.left, rc.top, rc.right - rc.left, rc.bottom - rc.top);
                    if (pe->tclr >= 0) {
                        COLORREF ck = (COLORREF)pe->tclr;
                        Gdiplus::ImageAttributes ia;
                        Gdiplus::Color cc(GetRValue(ck), GetGValue(ck), GetBValue(ck));
                        ia.SetColorKey(cc, cc);
                        g.DrawImage(im, dst, 0, 0, (int)im->GetWidth(), (int)im->GetHeight(), Gdiplus::UnitPixel, &ia);
                    } else {
                        g.DrawImage(im, dst.X, dst.Y, dst.Width, dst.Height);
                    }
                }
                return TRUE;
            }
        }
        if (dis && dis->CtlType == ODT_LISTBOX && yc_is_chklist((int)dis->CtlID) && dis->itemID != (UINT)-1) {
            HWND hLb = dis->hwndItem; RECT rc = dis->rcItem;
            BOOL sel = (dis->itemState & ODS_SELECTED) != 0;
            BOOL dis2 = g_ycChkDisabled[hLb][(int)dis->itemID] != 0;
            FillRect(dis->hDC, &rc, sel ? (HBRUSH)GetSysColorBrush(COLOR_HIGHLIGHT) : (HBRUSH)GetSysColorBrush(COLOR_WINDOW));
            int box = rc.bottom - rc.top - 4; if (box < 10) box = 10; if (box > 16) box = 16;
            RECT cb; cb.left = rc.left + 2; cb.top = rc.top + ((rc.bottom-rc.top-box)/2); cb.right = cb.left + box; cb.bottom = cb.top + box;
            UINT st = DFCS_BUTTONCHECK | DFCS_FLAT; if (g_ycChkChecked[hLb][(int)dis->itemID]) st |= DFCS_CHECKED; if (dis2) st |= DFCS_INACTIVE;
            DrawFrameControl(dis->hDC, &cb, DFC_BUTTON, st);
            wchar_t itxt[512] = L""; SendMessageW(hLb, LB_GETTEXT, dis->itemID, (LPARAM)itxt);
            SetBkMode(dis->hDC, TRANSPARENT);
            SetTextColor(dis->hDC, sel ? GetSysColor(COLOR_HIGHLIGHTTEXT) : (dis2 ? GetSysColor(COLOR_GRAYTEXT) : GetSysColor(COLOR_WINDOWTEXT)));
            RECT tr = rc; tr.left = cb.right + 4;
            DrawTextW(dis->hDC, itxt, -1, &tr, DT_SINGLELINE | DT_VCENTER | DT_LEFT | DT_NOPREFIX);
            if (dis->itemState & ODS_FOCUS) DrawFocusRect(dis->hDC, &dis->rcItem);
            return TRUE;
        }
        if (dis && dis->CtlType == ODT_BUTTON) {
            for (size_t bi = 0; bi < sizeof(g_ycButtonDraws) / sizeof(g_ycButtonDraws[0]); bi++) {
                if (g_ycButtonDraws[bi].id != (int)dis->CtlID) continue;
                RECT rc = dis->rcItem;
                BOOL pressed = (dis->itemState & ODS_SELECTED) != 0;
                COLORREF bg = g_ycButtonDraws[bi].bgColor;
                HBRUSH hbr = CreateSolidBrush(bg);
                FillRect(dis->hDC, &rc, hbr);
                DeleteObject(hbr);
                DrawEdge(dis->hDC, &rc, pressed ? EDGE_SUNKEN : EDGE_RAISED, BF_RECT);
                if (g_ycButtonDraws[bi].isDefault) { HBRUSH hbf = CreateSolidBrush(GetSysColor(COLOR_WINDOWFRAME)); FrameRect(dis->hDC, &dis->rcItem, hbf); DeleteObject(hbf); }
                wchar_t btxt[256] = L""; GetWindowTextW(dis->hwndItem, btxt, 256);
                HFONT hbfont = (HFONT)SendMessageW(dis->hwndItem, WM_GETFONT, 0, 0);
                HGDIOBJ oldF = hbfont ? SelectObject(dis->hDC, hbfont) : NULL;
                SetBkMode(dis->hDC, TRANSPARENT);
                SetTextColor(dis->hDC, g_ycButtonDraws[bi].textColor >= 0 ? (COLORREF)g_ycButtonDraws[bi].textColor : GetSysColor(COLOR_BTNTEXT));
                UINT fmt = DT_SINGLELINE;
                fmt |= (g_ycButtonDraws[bi].hAlign == 0) ? DT_LEFT : (g_ycButtonDraws[bi].hAlign == 2) ? DT_RIGHT : DT_CENTER;
                fmt |= (g_ycButtonDraws[bi].vAlign == 0) ? DT_TOP : (g_ycButtonDraws[bi].vAlign == 2) ? DT_BOTTOM : DT_VCENTER;
                RECT tr = rc; if (pressed) OffsetRect(&tr, 1, 1);
                DrawTextW(dis->hDC, btxt, -1, &tr, fmt);
                if (oldF) SelectObject(dis->hDC, oldF);
                if (dis->itemState & ODS_FOCUS) { RECT fr = dis->rcItem; InflateRect(&fr, -3, -3); DrawFocusRect(dis->hDC, &fr); }
                return TRUE;
            }
        }
        if (dis && dis->CtlType == ODT_STATIC) {
            for (size_t si = 0; si < sizeof(g_ycShapeBoxes) / sizeof(g_ycShapeBoxes[0]); si++) {
                if (g_ycShapeBoxes[si].id != (int)dis->CtlID) continue;
                RECT rc = dis->rcItem;
                HBRUSH hbg = CreateSolidBrush(g_ycShapeBoxes[si].backColor);
                FillRect(dis->hDC, &rc, hbg); DeleteObject(hbg);
                int shp = g_ycShapeBoxes[si].shape, ls = g_ycShapeBoxes[si].lineStyle;
                int psStyle = (ls==0)?PS_NULL:(ls==2)?PS_DASH:(ls==3)?PS_DOT:(ls==4)?PS_DASHDOT:(ls==5)?PS_DASHDOTDOT:PS_SOLID;
                int lw = g_ycShapeBoxes[si].lineWidth; if (lw < 1) lw = 1;
                HPEN hpen = CreatePen(psStyle, lw, g_ycShapeBoxes[si].lineColor);
                HBRUSH hfill = CreateSolidBrush(g_ycShapeBoxes[si].fillColor);
                HGDIOBJ oldPen = SelectObject(dis->hDC, hpen), oldBr = SelectObject(dis->hDC, hfill);
                int L = rc.left, T = rc.top, R = rc.right - 1, B = rc.bottom - 1;
                if (shp==1 || shp==3 || shp==5) { int s = (R-L < B-T) ? (R-L) : (B-T); R = L + s; B = T + s; }
                switch (shp) {
                    case 0: case 1: Rectangle(dis->hDC, L, T, R, B); break;
                    case 2: case 3: Ellipse(dis->hDC, L, T, R, B); break;
                    case 4: case 5: RoundRect(dis->hDC, L, T, R, B, (R-L)/4, (B-T)/4); break;
                    case 6: { int y=(T+B)/2; MoveToEx(dis->hDC, L, y, NULL); LineTo(dis->hDC, R, y); break; }
                    case 7: { int x=(L+R)/2; MoveToEx(dis->hDC, x, T, NULL); LineTo(dis->hDC, x, B); break; }
                }
                SelectObject(dis->hDC, oldPen); SelectObject(dis->hDC, oldBr);
                DeleteObject(hpen); DeleteObject(hfill);
                if (g_ycShapeBoxes[si].effect==1) DrawEdge(dis->hDC, &rc, EDGE_SUNKEN, BF_RECT);
                else if (g_ycShapeBoxes[si].effect==2) DrawEdge(dis->hDC, &rc, EDGE_RAISED, BF_RECT);
                return TRUE;
            }
        }
        break;
    }
    case WM_MEASUREITEM: {
        LPMEASUREITEMSTRUCT mis = (LPMEASUREITEMSTRUCT)lParam;
        if (mis && mis->CtlType == ODT_LISTBOX && yc_is_chklist((int)mis->CtlID)) { mis->itemHeight = 18; return TRUE; }
        break;
    }
    case WM_PRINTCLIENT: {
        HDC hdc = (HDC)wParam;
        RECT prc; GetClientRect(hWnd, &prc);
        FillRect(hdc, &prc, g_hFormBgBrush ? g_hFormBgBrush : GetSysColorBrush(COLOR_BTNFACE));
        return 0;
    }
    case WM_PAINT: {
        PAINTSTRUCT ps;
        HDC hdc = BeginPaint(hWnd, &ps);
        EndPaint(hWnd, &ps);
        break;
    }
    case WM_KEYDOWN:
    case WM_SYSKEYDOWN:
        __启动窗口_按下某键((int)wParam, (int)lParam);
        break;
    case WM_KEYUP:
    case WM_SYSKEYUP:
        __启动窗口_某键被放开((int)wParam, (int)lParam);
        break;
    case WM_MOUSEWHEEL: {
        POINT wpt; wpt.x = (int)(short)LOWORD(lParam); wpt.y = (int)(short)HIWORD(lParam);
        HWND hUnder = WindowFromPoint(wpt);
        if (hUnder && IsWindowEnabled(hUnder)) {
            int wid = GetDlgCtrlID(hUnder);
            for (size_t pi = 0; pi < sizeof(g_ycPicBoxMouse)/sizeof(g_ycPicBoxMouse[0]); pi++) {
                if (g_ycPicBoxMouse[pi].id != wid) continue;
                if (g_ycPicBoxMouse[pi].wheel && g_ycPicBoxMouse[pi].wheel((int)(short)HIWORD(wParam), yc_pb_fkeys((WPARAM)LOWORD(wParam)))) return 0;
                break;
            }
        }
        return DefWindowProcW(hWnd, message, wParam, lParam);
    }
    case WM_SIZE:
        __启动窗口_窗口尺寸被改变((int)LOWORD(lParam), (int)HIWORD(lParam));
        break;
    case WM_MOVE:
        __启动窗口_被移动((int)(short)LOWORD(lParam), (int)(short)HIWORD(lParam));
        break;
    case WM_ACTIVATE:
        __启动窗口_被激活((int)LOWORD(wParam));
        break;
    case WM_SETFOCUS:
        __启动窗口_得到焦点();
        break;
    case WM_KILLFOCUS:
        __启动窗口_失去焦点();
        break;
    case WM_CLOSE:
        __启动窗口_即将被销毁();
        DestroyWindow(hWnd);
        break;
    case WM_DESTROY:
        __启动窗口_被销毁();
        g_hMainWnd = NULL;
        if (!yc_any_window_alive()) PostQuitMessage(0);
        break;
    case WM_SYSCOMMAND:
        if ((wParam & 0xFFF0) == SC_MOVE) return 0;
        return DefWindowProcW(hWnd, message, wParam, lParam);
    case WM_NCACTIVATE:
        return DefWindowProcW(hWnd, message, TRUE, lParam);
    default:
        return DefWindowProcW(hWnd, message, wParam, lParam);
    }
    return 0;
}

int yc_win_load(const wchar_t* name, const wchar_t* parentName, int dialogMode) {
    (void)parentName; (void)dialogMode;
    if (name && lstrcmpW(name, L"_启动窗口") == 0 && g_hMainWnd) { ShowWindow(g_hMainWnd, SW_SHOW); SetForegroundWindow(g_hMainWnd); return 1; }
    return 0;
}
void yc_win_destroy(const wchar_t* name) {
    HWND h = yc_get_control_handle_by_name(name);
    if (h && IsWindow(h)) DestroyWindow(h);
}

static void ycActivateVisualStyle(void) {
#ifdef YC_VC6_STYLE
    char exePath[MAX_PATH];
    GetModuleFileNameA(NULL, exePath, MAX_PATH);
    ACTCTXA ac;
    ZeroMemory(&ac, sizeof(ac));
    ac.cbSize = sizeof(ac);
    ac.lpSource = exePath;
    ac.dwFlags = ACTCTX_FLAG_RESOURCE_NAME_VALID;
    ac.lpResourceName = MAKEINTRESOURCEA(1);
    HANDLE hCtx = CreateActCtxA(&ac);
    if (hCtx != INVALID_HANDLE_VALUE) {
        ULONG_PTR cookie = 0;
        ActivateActCtx(hCtx, &cookie);
    }
#endif
}

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance,
                   LPSTR lpCmdLine, int nCmdShow) {
    /* VC6 现代样式：先建立激活上下文，再初始化通用控件与任何窗口 */
    ycActivateVisualStyle();
    /* 重定向 stdout 到父进程管道（使调试输出可被 IDE 捕获） */
    HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);
    if (hOut && hOut != INVALID_HANDLE_VALUE) {
        int fd = _open_osfhandle((intptr_t)hOut, _O_TEXT);
        if (fd >= 0) {
            FILE* fp = _fdopen(fd, "w");
            if (fp) { *stdout = *fp; setvbuf(stdout, NULL, _IONBF, 0); }
        }
    }
    g_hInstance = hInstance;
    INITCOMMONCONTROLSEX icc = { sizeof(INITCOMMONCONTROLSEX), ICC_WIN95_CLASSES | ICC_STANDARD_CLASSES | ICC_BAR_CLASSES | ICC_LISTVIEW_CLASSES | ICC_TREEVIEW_CLASSES | ICC_TAB_CLASSES | ICC_DATE_CLASSES | ICC_LINK_CLASSES };
    InitCommonControlsEx(&icc);
    { Gdiplus::GdiplusStartupInput gdiplusStartupInput;
      Gdiplus::GdiplusStartup(&g_gdiplusToken, &gdiplusStartupInput, NULL);
    }
    { WNDCLASSEXW dpwc; ZeroMemory(&dpwc, sizeof(dpwc)); dpwc.cbSize = sizeof(WNDCLASSEXW); dpwc.style = CS_HREDRAW | CS_VREDRAW; dpwc.lpfnWndProc = YcDrawPanelProc; dpwc.cbClsExtra = 0; dpwc.cbWndExtra = 0; dpwc.hInstance = hInstance; dpwc.hCursor = LoadCursor(NULL, IDC_ARROW); dpwc.hbrBackground = NULL; dpwc.lpszClassName = L"YCDRAWPANEL"; RegisterClassExW(&dpwc); }
    WNDCLASSEXW wcex;
    wcex.cbSize = sizeof(WNDCLASSEXW);
    wcex.style = CS_HREDRAW | CS_VREDRAW;
    wcex.lpfnWndProc = WndProc;
    wcex.cbClsExtra = 0;
    wcex.cbWndExtra = 0;
    wcex.hInstance = hInstance;
    wcex.hIcon = LoadIcon(NULL, IDI_APPLICATION);
    wcex.hCursor = LoadCursor(NULL, IDC_IBEAM);
    g_hFormBgBrush = CreateSolidBrush((COLORREF)16711680);
    wcex.hbrBackground = g_hFormBgBrush;
    wcex.lpszMenuName = NULL;
    wcex.lpszClassName = g_szClassName;
    wcex.hIconSm = LoadIcon(NULL, IDI_APPLICATION);
    if (!RegisterClassExW(&wcex)) {
        MessageBoxW(NULL, L"窗口类注册失败!", L"错误", MB_ICONERROR);
        return 1;
    }
    DWORD dwStyle = WS_OVERLAPPED | WS_CAPTION;
    DWORD dwExStyle = WS_EX_TOPMOST | WS_EX_DLGMODALFRAME | WS_EX_TOOLWINDOW;
    RECT rc = { 0, 0, g_nWidth, g_nHeight };
    AdjustWindowRectEx(&rc, dwStyle, FALSE, dwExStyle);
    int winW = rc.right - rc.left;
    int winH = rc.bottom - rc.top;
    int screenW = GetSystemMetrics(SM_CXSCREEN);
    int screenH = GetSystemMetrics(SM_CYSCREEN);
    int posX = (screenW - winW) / 2;
    int posY = (screenH - winH) / 2;
    HWND hWnd = CreateWindowExW(dwExStyle, g_szClassName, g_szTitle,
        dwStyle,
        posX, posY, winW, winH,
        NULL, NULL, hInstance, NULL);
    if (!hWnd) {
        MessageBoxW(NULL, L"窗口创建失败!", L"错误", MB_ICONERROR);
        return 1;
    }
    g_hMainWnd = hWnd;
    { RECT wrc; GetWindowRect(hWnd, &wrc);
      int rgnW = wrc.right - wrc.left; int rgnH = wrc.bottom - wrc.top;
      int rr = 12;
      int rrMax = (rgnW < rgnH ? rgnW : rgnH) / 2; if (rr > rrMax) rr = rrMax; if (rr < 0) rr = 0;
      HRGN hRgn = CreateRoundRectRgn(0, 0, rgnW + 1, rgnH + 1, rr * 2, rr * 2);
      if (hRgn) SetWindowRgn(hWnd, hRgn, TRUE);
    }
    ShowWindow(hWnd, nCmdShow);
    UpdateWindow(hWnd);
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        if (msg.message == WM_KEYDOWN && msg.wParam == VK_ESCAPE) {
            PostMessage(g_hMainWnd, WM_CLOSE, 0, 0);
            continue;
        }
        if (msg.message == WM_KEYDOWN && msg.wParam == VK_RETURN) {
            HWND ycFocus = GetFocus();
            wchar_t ycCls[16] = L""; if (ycFocus) GetClassNameW(ycFocus, ycCls, 16);
            BOOL ycMlEdit = (lstrcmpiW(ycCls, L"Edit") == 0) && (GetWindowLongW(ycFocus, GWL_STYLE) & ES_MULTILINE);
            if (!ycMlEdit) {
                HWND ycNext = GetNextDlgTabItem(g_hMainWnd, ycFocus, FALSE);
                if (ycNext && ycNext != ycFocus) { SetFocus(ycNext); continue; }
            }
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    return (int)msg.wParam;
}
